import SwiftUI
struct RootView: View { @EnvironmentObject var store: AppStore; var body: some View { Group { if store.isAuthenticated { MainTabs() } else { LoginView() } } } }
struct MainTabs: View { @EnvironmentObject var store: AppStore; var body: some View { TabView { if store.currentUser?.role == "professional" { ProfessionalDashboardView().tabItem{Label("Workspace",systemImage:"briefcase.fill")} } else { CustomerHomeView().tabItem{Label("Home",systemImage:"house.fill")}; DiscoveryView().tabItem{Label("Discover",systemImage:"sparkle.magnifyingglass")} }; BookingsView().tabItem{Label("Bookings",systemImage:"calendar")}; MessagesView().tabItem{Label("Messages",systemImage:"bubble.left.and.bubble.right")}; ProfileView().tabItem{Label("Profile",systemImage:"person.crop.circle")} }.tint(DopenexaColor.brand) } }
